import {describe, it, expect} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('Reproduction', () => {
  it('checks the error message for wrong type', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'ssn_lookup',
        description: 'Look up record by identifier',
        inputSchema: {
          type: 'object',
          properties: {ssn: {type: 'string'}},
          required: ['ssn'],
        },
      },
      async () => 'found'
    );

    const response = await registry.execute('ssn_lookup', {ssn: 123456789});
    console.log('REPRO RESULT:', response.result);
    expect(response.result).toContain('ssn');
  });
});

