import {describe, it, expect} from '@jest/globals';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry Field Mention', () => {
  it('mentions the field even if instancePath is empty', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'test_tool',
        description: 'A tool',
        inputSchema: {
          type: 'object',
          properties: {field1: {type: 'string'}},
          required: ['field1'],
        },
      },
      async () => 'ok'
    );

    // Simulate a type error where instancePath might be missing/empty
    // We can't easily mock Ajv internal error generation without deep mocking
    // But we can check if our current implementation fails if we force it.

    const response = await registry.execute('test_tool', {field1: 123});
    expect(response.result).toContain('field1');
  });
});

