/** Validates input against the registered schema and executes the tool; see specs/hal-engine-tool-input-validation/spec.md */
async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
  const tool = this.tools.get(name);
  if (!tool) {
    log.warn('tool', 'tool not found', {name});
    throw new Error(`Unknown tool: ${name}`);
  }

  const definition = this.resolveDefinition(tool.definitionSource);
  let validate = this.validatorCache.get(definition.inputSchema);
  if (!validate) {
    validate = this.ajv.compile(definition.inputSchema);
    if (validate) {
      this.validatorCache.set(definition.inputSchema, validate);
    }
  }

  if (!validate || !validate(input)) {
    const errors = (validate?.errors as any[]) ?? [];
    const message = errors
      .map((e: any) => {
        const path = e.instancePath || e.dataPath || '';
